"Biografia":"Биография",
"Nascido a 13 de setembro de 2009, Alfredo Bidarra é defesa central do Lisbon FC desde a fundação do clube, a 1 de março de 2023. Os seus primeiros passos no futebol deram-se de forma informal, no campo da Escola de Música do Conservatório Musical, onde jogava com amigos antes de se juntar ao projeto do Lisbon FC logo desde o início.":"Альфреду Бидарра родился 13 сентября 2009 года и выступает за Lisbon FC на позиции центрального защитника с момента основания клуба 1 марта 2023 года. Свои первые шаги в футболе он сделал неформально — на поле Музыкальной школы Консерватории, где играл с друзьями, прежде чем с самого начала присоединиться к проекту Lisbon FC.",
"Fisicamente forte e com um espírito de liderança evidente dentro de campo, Alfredo Bidarra é uma referência na defesa da equipa, destacando-se pelo seu espírito de equipa e pela solidez que transmite aos companheiros. Um dos momentos mais marcantes da sua passagem pelo clube foi a conquista da Supertaça 2024, um título que ajudou a construir com a sua presença segura na linha defensiva.":"Физически сильный и с явными лидерскими качествами на поле, Альфреду Бидарра — опора обороны команды, выделяющийся командным духом и надёжностью, которую он передаёт партнёрам. Одним из самых ярких моментов его пути в клубе стала победа в Суперкубке 2024 — титул, который он помог завоевать своей уверенной игрой в линии обороны.",
"Fora das quatro linhas, frequenta o 12º ano no curso de Ciências, procurando equilibrar da melhor forma a carreira futebolística com os estudos, numa fase da vida em que ambos os percursos exigem dedicação e disciplina.":"Вне поля он учится в 12-м классе по естественно-научному профилю, стараясь как можно лучше совмещать футбольную карьеру с учёбой в период жизни, когда оба пути требуют преданности и дисциплины.",
