"Detalhes":"Подробности",
"A Camisola Principal do Lisbon FC 2026-2027 mantém as cores históricas do clube, o azul-marinho e o amarelo, num design limpo com a faixa central que atravessa o peito. Tecido leve e respirável, pensado para acompanhar a equipa em cada jogo da época. Inspirada na ligação do clube à cidade, a camisola traz ainda um padrão subtil junto às costuras, o emblema do Lisbon FC bordado ao peito e a gola em V com remate branco. Um equipamento pensado tanto para o dia de jogo como para o dia a dia dos adeptos.":"Домашняя футболка Lisbon FC 2026-2027 сохраняет исторические цвета клуба — тёмно-синий и жёлтый — в лаконичном дизайне с центральной полосой через грудь. Лёгкая дышащая ткань, созданная, чтобы поддерживать команду в каждом матче сезона. Вдохновлённая связью клуба с городом, футболка также имеет едва заметный узор вдоль швов, вышитую на груди эмблему Lisbon FC и V-образный вырез с белой окантовкой. Форма, созданная как для дня матча, так и для повседневной жизни болельщиков.",
"Entregas e devoluções":"Доставка и возврат",
"Encomendas para Portugal Continental são entregues no prazo de":"Заказы по континентальной Португалии доставляются в течение",
"24 a 48 horas úteis":"24–48 рабочих часов",
", a contar da confirmação do pagamento.":"с момента подтверждения оплаты.",
"Após a receção da encomenda, dispõe de um prazo de":"После получения заказа у вас есть",
"30 dias":"30 дней",
"para solicitar troca ou devolução.":"чтобы запросить обмен или возврат.",
"Mais informações":"Подробнее",
"Partilhar":"Поделиться",
"Tamanhos":"Размеры",
"A Camisola Principal do Lisbon FC 2026-2027 mantém as cores históricas do clube, o azul-marinho e o amarelo, num design limpo com a faixa central que atravessa o peito. Tecido leve e respirável, pensado para acompanhar a equipa em cada jogo da época. Inspirada na ligação do clube à cidade, a camisola traz ainda um padrão subtil junto às costuras, o emblema do Lisbon FC bordado ao peito e a gola em V com remate branco.":"Домашняя футболка Lisbon FC 2026-2027 сохраняет исторические цвета клуба — тёмно-синий и жёлтый — в лаконичном дизайне с центральной полосой через грудь. Лёгкая дышащая ткань, созданная, чтобы поддерживать команду в каждом матче сезона. Вдохновлённая связью клуба с городом, футболка также имеет едва заметный узор вдоль швов, вышитую на груди эмблему Lisbon FC и V-образный вырез с белой окантовкой.",
"O tecido é feito num material técnico de secagem rápida, com zonas ventiladas nas costas e por baixo dos braços para maior conforto durante o esforço. As mangas curtas têm um corte anatómico que acompanha o movimento do jogador sem restringir a mobilidade do ombro.":"Ткань изготовлена из быстросохнущего технического материала с вентилируемыми зонами на спине и под руками для большего комфорта при нагрузке. Короткие рукава имеют анатомический крой, который следует за движениями игрока, не ограничивая подвижность плеча.",
"Um equipamento pensado tanto para o dia de jogo como para o dia a dia dos adeptos, fácil de combinar e preparado para aguentar o uso frequente sem perder a cor nem a forma.":"Форма, созданная как для дня матча, так и для повседневной жизни болельщиков: легко сочетается и выдерживает частую носку, не теряя цвета и формы.",
"Lavar à máquina até 30ºC, do avesso e sem lixívia. Não usar secador nem passar a ferro sobre o emblema.":"Машинная стирка до 30 ºC, наизнанку, без отбеливателя. Не сушить в машине и не гладить по эмблеме.",
