"Consinto, de forma livre, consciente e informada, que o Lisbon FC recolha e trate os dados pessoais por mim fornecidos para ações de marketing e publicidade, pressupondo esse tratamento a comunicação dos meus dados ao Grupo Lisbon FC, bem como a criação de um perfil, de forma a enviar comunicações ajustadas aos meus interesses, nomeadamente sendo possível personalizar o meu consentimento através da criação de uma conta My LisbonFC, nos termos melhor descritos na Política de Privacidade do Grupo Lisbon FC.":"Я свободно, осознанно и информированно даю согласие на то, чтобы Lisbon FC собирал и обрабатывал предоставленные мной персональные данные для маркетинговых и рекламных целей, что предполагает передачу моих данных Группе Lisbon FC, а также создание профиля для отправки сообщений с учётом моих интересов; в частности, своё согласие можно настроить, создав аккаунт My LisbonFC, как подробнее описано в Политике конфиденциальности Группы Lisbon FC.",
