"Moda Criança do Lisbon FC. T-shirts, polos, treino, calças e calções oficiais.":"Детская мода Lisbon FC. Официальные футболки, поло, тренировочная одежда, брюки и шорты.",
"São Petersburgo":"Санкт-Петербург",
"Nacionalidade":"Гражданство",
"Russa":"Россия",
"Nascida a 13 de janeiro de 2008, Daria Vinokurova completou 18 anos em 2026. Iniciou o seu percurso no futebol na Rússia, ao serviço do Zenit de São Petersburgo. Ao mudar-se para Portugal, juntou-se ao Torreense, clube de Torres Vedras, cidade onde reside. Após três temporadas no clube, e devido a pouco tempo de jogo, transferiu-se para o Estoril Praia Futebol Clube, onde passou uma época e assumiu o papel de capitã de equipa — a sua primeira temporada a competir na primeira divisão nacional. Para a época 2026/27, rumou ao clube de futebol feminino Racing Power FC, continuando a sua carreira como atleta.":"Дарья Винокурова родилась 13 января 2008 года, в 2026 году ей исполнилось 18 лет. Свой путь в футболе она начала в России, в петербургском «Зените». Переехав в Португалию, она присоединилась к «Торреэнсе» — клубу из Торриш-Ведраша, города, где она живёт. После трёх сезонов в клубе из-за недостатка игрового времени она перешла в «Эшторил Прая», где провела один сезон и стала капитаном команды — это был её первый сезон в высшем национальном дивизионе. На сезон 2026/27 она перешла в женский футбольный клуб Racing Power FC, продолжив карьеру игрока.",
"Paralelamente, Daria Vinokurova abraçou o projeto do Lisbon FC, assumindo a 29 de janeiro de 2026 o seu primeiro cargo de sempre como treinadora, tornando-se treinadora principal da equipa. Com uma excelente leitura de jogo, forte liderança e um espírito exemplar — qualidades já evidentes no seu percurso como capitã enquanto atleta —, Daria rapidamente se tornou uma referência dentro do balneário. Ainda não orientou o Lisbon FC em competição oficial, mas fá-lo-á em breve: a defesa do título na Supertaça 2026 será a sua estreia oficial como treinadora.":"Параллельно Дарья Винокурова присоединилась к проекту Lisbon FC, 29 января 2026 года впервые заняв тренерскую должность и став главным тренером команды. Благодаря отличному пониманию игры, сильным лидерским качествам и образцовому характеру — качествам, которые проявились ещё в её капитанстве, — Дарья быстро стала авторитетом в раздевалке. Она ещё не руководила Lisbon FC в официальных матчах, но скоро это сделает: защита титула в Суперкубке 2026 станет её официальным тренерским дебютом.",
"Em criança, Daria praticava ginástica artística a alto nível, mas com o passar do tempo viu-se obrigada a escolher entre a ginástica e o futebol. O seu coração pendeu para o futebol, e foi essa a modalidade que decidiu seguir. Tem ainda duas irmãs mais novas. A treinadora sonha em tornar-se jogadora de futebol profissional e trabalha diariamente para esse objetivo, ao mesmo tempo que orienta o Lisbon FC na conquista da tão cobiçada Supertaça.":"В детстве Дарья занималась спортивной гимнастикой на высоком уровне, но со временем ей пришлось выбирать между гимнастикой и футболом. Её сердце склонилось к футболу, и именно этим видом спорта она решила заниматься. У неё также есть две младшие сестры. Тренер мечтает стать профессиональной футболисткой и ежедневно работает ради этой цели, одновременно ведя Lisbon FC к завоеванию столь желанного Суперкубка.",
"Daria Vinokurova, Treinadora Principal do Lisbon FC.":"Дарья Винокурова, главный тренер Lisbon FC.",
