"Adere ao Débito Direto e paga as tuas quotas de sócio do Lisbon FC automaticamente.":"Подключите прямое дебетование и оплачивайте членские взносы Lisbon FC автоматически.",
"Médio":"Полузащитник",
"Nascido em Lisboa a 14 de setembro de 2008, Duarte Silva é um jogador polivalente, atuando predominantemente como médio-centro. Começou por jogar futebol de forma descontraída com amigos, mas foi a 17 de março de 2026, dia em que assinou pelo Lisbon FC, que decidiu dedicar-se verdadeiramente à modalidade.":"Дуарте Силва родился в Лиссабоне 14 сентября 2008 года. Это универсальный игрок, выступающий преимущественно в роли центрального полузащитника. Он начинал играть в футбол непринуждённо с друзьями, но 17 марта 2026 года, в день подписания контракта с Lisbon FC, решил по-настоящему посвятить себя этому виду спорта.",
"A sua principal característica é a velocidade: ganha praticamente qualquer duelo de um-para-um em corrida, aliando essa capacidade a uma boa dose de habilidade nas fintas. Estas qualidades tornam-no rapidamente numa das peças fundamentais do plantel. Ainda aguarda a oportunidade de fazer a sua estreia oficial pelo Lisbon FC, com a defesa do título na Supertaça 2026 a apontar-se como o primeiro grande desafio no horizonte do médio.":"Его главное качество — скорость: он выигрывает практически любую дуэль один на один в беге, сочетая это с хорошей техникой финтов. Эти качества быстро делают его одним из ключевых игроков состава. Он всё ещё ждёт возможности официально дебютировать за Lisbon FC, и защита титула в Суперкубке 2026 станет первым большим испытанием для полузащитника.",
"Fora do relvado, Duarte Silva frequenta o 12º ano do curso de Produção e Tecnologias da Música, toca guitarra e é escuteiro, dividindo o seu tempo entre a música, o escutismo e a crescente dedicação ao futebol.":"Вне поля Дуарте Силва учится в 12-м классе по направлению «Музыкальное производство и технологии», играет на гитаре и состоит в скаутах, деля время между музыкой, скаутингом и растущей преданностью футболу.",
"Duarte Silva, Médio do Lisbon FC.":"Дуарте Силва, полузащитник Lisbon FC.",
"Avançado":"Нападающий",
"Corunha, Espanha":"Ла-Корунья, Испания",
"Nascido na Corunha, Espanha, a 15 de março de 2009, Eduardo Demidenko Sánchez é ponta de lança do Lisbon FC e o melhor marcador da história do clube, com 6 golos. Sempre gostou de futebol, mas foi no campo do Conservatório Nacional, a jogar com amigos em todos os intervalos, que foi aperfeiçoando as suas capacidades. Assinou o seu primeiro contrato com o maior clube de Lisboa a 28 de setembro de 2022, dando início a uma ligação mais profissional à modalidade, com treinos e jogos oficiais, ligação essa que se prolongou através de sucessivas renovações de contrato.":"Эдуардо Демиденко Санчес родился в Ла-Корунье (Испания) 15 марта 2009 года. Он центральный нападающий Lisbon FC и лучший бомбардир в истории клуба — 6 голов. Он всегда любил футбол, но оттачивал своё мастерство на поле Национальной консерватории, играя с друзьями на каждой перемене. Первый контракт с крупнейшим клубом Лиссабона он подписал 28 сентября 2022 года, положив начало более профессиональной связи со спортом — с тренировками и официальными матчами; эта связь продолжилась благодаря последующим продлениям контракта.",
"Matador dentro de área, com uma finalização apurada e boa técnica de penáltis, Eduardo Sánchez é atualmente a segunda opção da equipa para bater grandes penalidades. A sua passagem pelo clube está repleta de momentos marcantes, mas dois destacam-se especialmente: o poker de golos apontado no jogo de abertura do Lisbon FC, a 1 de março de 2023, num emocionante empate 4-4 (com a equipa acabando por perder na marcação de grandes penalidades), e o golo que fechou o marcador na conquista da Supertaça 2024.":"Убийственный в штрафной, с точным завершением атак и хорошей техникой пенальти, Эдуардо Санчес сейчас второй в команде по очереди исполнения одиннадцатиметровых. Его путь в клубе полон ярких моментов, но два выделяются особо: покер в первом матче Lisbon FC 1 марта 2023 года в захватывающей ничьей 4:4 (команда в итоге проиграла в серии пенальти) и гол, установивший окончательный счёт в победном Суперкубке 2024.",
"O nome \"Demidenko\" vem do seu pai, russo, enquanto \"Sánchez\" é herdado da sua mãe, espanhola. Possui dupla nacionalidade russa e espanhola, tendo entretanto adquirido também a nacionalidade portuguesa. Apesar da riqueza das suas origens, Eduardo Sánchez identifica-se sobretudo como espanhol e sonha um dia representar a seleção espanhola, um objetivo que o Lisbon FC também abraça e ambiciona ajudar a concretizar.":"Фамилия «Демиденко» досталась ему от отца-россиянина, а «Санчес» — от матери-испанки. У него двойное гражданство России и Испании, а впоследствии он получил и португальское. Несмотря на богатство своего происхождения, Эдуардо Санчес прежде всего считает себя испанцем и мечтает однажды сыграть за сборную Испании — цель, которую Lisbon FC тоже разделяет и стремится помочь осуществить.",
"Eduardo Sánchez, Avançado do Lisbon FC.":"Эдуардо Санчес, нападающий Lisbon FC.",
