"Gestão de Moradas":"Управление адресами",
"Os cartões guardados na tua conta Lisbon FC.":"Карты, сохранённые в вашем аккаунте Lisbon FC.",
"Esquerdo":"Левая",
"Nascido em Lisboa a 7 de julho de 2009, Gonçalo Pereira veste a camisola número 7 do Lisbon FC. Jogador versátil, capaz de atuar em várias posições, as suas funções predominantes são lateral e ponta de lança. Tal como a maioria dos seus colegas de equipa, começou a jogar futebol nos intervalos, no campo do Conservatório Nacional. Foi, no entanto, no Mundial de 2022 que Gonçalo Pereira se apaixonou verdadeiramente pelo futebol, começando a aprofundar o seu conhecimento sobre a modalidade e reforçando a sua admiração pelo ídolo Cristiano Ronaldo.":"Гонсалу Перейра родился в Лиссабоне 7 июля 2009 года и носит в Lisbon FC футболку с номером 7. Универсальный игрок, способный играть на разных позициях; основные его роли — крайний защитник и центральный нападающий. Как и большинство партнёров по команде, он начал играть в футбол на переменах на поле Национальной консерватории. Однако по-настоящему влюбился в футбол Гонсалу Перейра во время чемпионата мира 2022 года, начав глубже изучать этот вид спорта и укрепив восхищение своим кумиром Криштиану Роналду.",
"Juntou-se ao Lisbon FC alguns meses antes da abertura oficial do clube, somando já quatro jogos ao serviço da equipa. Fisicamente forte e um excelente batedor de bolas paradas, Gonçalo Pereira teve um papel decisivo na vitória por 4-2 na Supertaça 2024, na qual apontou dois golos, um dos momentos mais marcantes da sua passagem pelo clube.":"Он присоединился к Lisbon FC за несколько месяцев до официального открытия клуба и уже провёл за команду четыре матча. Физически сильный и отличный исполнитель стандартов, Гонсалу Перейра сыграл решающую роль в победе 4:2 в Суперкубке 2024, забив два гола, — один из самых ярких моментов его пути в клубе.",
"Para manter uma atividade futebolística diária, esteve dois anos na escola de futebol do Belenenses, mudando-se em setembro de 2025 para a formação do Operário FC. Ainda assim, o seu clube de coração continua a ser o Lisbon FC, o clube que, para Gonçalo Pereira, é aquele que mais lhe dá.":"Чтобы ежедневно заниматься футболом, он два года провёл в футбольной школе «Белененсеш», а в сентябре 2025 года перешёл в академию «Операриу». И всё же клубом его сердца остаётся Lisbon FC — клуб, который, по мнению Гонсалу Перейры, даёт ему больше всего.",
"Gonçalo Pereira, Avançado do Lisbon FC.":"Гонсалу Перейра, нападающий Lisbon FC.",
"Nascido em Lisboa a 11 de setembro de 2009, Gonçalo Rodrigues é o atual capitão do Lisbon FC, título que carrega em ambas as passagens que teve pelo clube. Tal como muitos dos seus companheiros, aprendeu a jogar futebol de forma informal, nos intervalos da escola, ao lado dos amigos. Começou a encarar o desporto com mais seriedade após assinar pelo Lisbon FC em 2022, ainda antes da fundação oficial do clube.":"Гонсалу Родригеш родился в Лиссабоне 11 сентября 2009 года и является нынешним капитаном Lisbon FC — это звание он носил в обоих периодах своей игры за клуб. Как и многие партнёры, он научился играть в футбол неформально, на школьных переменах вместе с друзьями. Серьёзнее относиться к спорту он начал после подписания контракта с Lisbon FC в 2022 году, ещё до официального основания клуба.",
"Depois de dois anos ao serviço da equipa, Gonçalo Rodrigues viu-se obrigado a abandonar o Lisbon FC ao sair do Conservatório Nacional, ficando de fora do projeto dos \"Corvos\". Rumou então a Odivelas, onde passou um ano a aperfeiçoar as suas capacidades. Quando o clube deixou de estar ligado à escola e passou a jogar \"nas ruas\", Gonçalo regressou ao Lisbon FC ao fim de um ano de ausência, reforçando de novo o projeto que ajudara a construir desde cedo.":"После двух лет в команде Гонсалу Родригешу пришлось покинуть Lisbon FC, когда он ушёл из Национальной консерватории, и выбыть из проекта «Воронов». Затем он отправился в Одивелаш, где год совершенствовал своё мастерство. Когда клуб перестал быть связан со школой и начал играть «на улицах», Гонсалу вернулся в Lisbon FC после года отсутствия, вновь усилив проект, который помогал строить с самого начала.",
"Dono de um remate apurado, boa visão de jogo, liderança nata e uma robustez física acima da média, Gonçalo Rodrigues é uma peça-chave da equipa. Um dos momentos mais marcantes da sua carreira no clube aconteceu logo no segundo jogo oficial do Lisbon FC, quando apontou um bis com dois golos fantásticos.":"Обладатель точного удара, хорошего видения поля, природного лидерства и физической мощи выше среднего, Гонсалу Родригеш — ключевой игрок команды. Один из самых ярких моментов его карьеры в клубе случился уже во втором официальном матче Lisbon FC, когда он оформил дубль, забив два фантастических гола.",
"Fora do futebol, foi durante largos anos violinista no Conservatório Nacional, instrumento que acabou por abandonar, e atualmente está a aprender a tocar saxofone. O seu grande sonho é tornar-se jogador de futebol profissional, uma ambição que o Lisbon FC também partilha e trabalha arduamente para tornar realidade.":"Вне футбола он много лет играл на скрипке в Национальной консерватории, но в итоге оставил этот инструмент, а сейчас учится играть на саксофоне. Его большая мечта — стать профессиональным футболистом; эту цель разделяет и Lisbon FC, упорно работая над её осуществлением.",
"Gonçalo Rodrigues, Defesa Central do Lisbon FC.":"Гонсалу Родригеш, центральный защитник Lisbon FC.",
