"A caminhar para o terceiro ano de existência, o clube olha para trás com orgulho no percurso feito dentro e fora de campo.":"Приближаясь к третьему году существования, клуб с гордостью оглядывается на путь, пройденный на поле и за его пределами.",
"O primeiro grande troféu da história do clube foi erguido em 2024, com um novo capítulo já a caminho em 2026.":"Первый крупный трофей в истории клуба был завоёван в 2024 году, а в 2026 году уже готовится новая глава.",
