"Existem alguns dados que não estão de momento disponíveis para editar / alterar. Caso pretendas modificar algum desses dados, utiliza os canais oficiais do Lisbon FC.":"Некоторые данные сейчас недоступны для редактирования / изменения. Если вы хотите изменить какие-либо из них, воспользуйтесь официальными каналами Lisbon FC.",
"*Caso o formato da fotografia do cartão não cumpra as regras, poderá ser emitido sem a respetiva fotografia.":"*Если формат фотографии для карты не соответствует правилам, карта может быть выпущена без фотографии.",
