"Loja oficial do Lisbon FC. Equipamentos, linha de treino e acessórios da época 2026/27.":"Официальный магазин Lisbon FC. Форма, тренировочная линия и аксессуары сезона 2026/27.",
"Nascido em Lisboa a 16 de janeiro de 2010, Martim Neves é o mais recente reforço do plantel do Lisbon FC, atuando na posição de médio-centro. Deu os primeiros passos no futebol no Sporting Clube de Linda-a-Velha, antes de se transferir para o Lisbon FC a 18 de março de 2026.":"Мартин Невеш родился в Лиссабоне 16 января 2010 года и является самым свежим пополнением состава Lisbon FC, играя на позиции центрального полузащитника. Первые шаги в футболе он сделал в «Спортинг Клубе де Линда-а-Велья», а 18 марта 2026 года перешёл в Lisbon FC.",
"Ainda em fase de desenvolvimento, Martim Neves destaca-se sobretudo pela sua visão de jogo e pela qualidade dos passes rasteiros, características que prometem torná-lo uma peça importante no meio-campo da equipa. Ainda não fez a sua estreia oficial, mas o primeiro jogo está à vista: a defesa do título na Supertaça 2026.":"Ещё находясь в стадии развития, Мартин Невеш выделяется прежде всего видением поля и качеством передач низом — качествами, которые обещают сделать его важной фигурой в полузащите команды. Официального дебюта у него пока не было, но первый матч уже на горизонте: защита титула в Суперкубке 2026.",
"Fora do futebol, frequenta os escuteiros juntamente com o seu colega de equipa Duarte Silva, tendo sido precisamente aí que os dois se conheceram e construíram uma amizade que hoje também partilham dentro do plantel.":"Вне футбола он состоит в скаутах вместе с партнёром по команде Дуарте Силвой — именно там они познакомились и подружились, а теперь делят эту дружбу и в составе команды.",
"Martim Neves, Médio do Lisbon FC.":"Мартин Невеш, полузащитник Lisbon FC.",
