"O cartão físico é enviado para a tua morada depois de confirmados os teus dados. Até lá, usa o cartão digital na App Lisbon FC para comprar bilhetes e aceder a todos os serviços e benefícios de sócio.":"Физическая карта отправляется на ваш адрес после подтверждения данных. А пока используйте цифровую карту в приложении Lisbon FC, чтобы покупать билеты и пользоваться всеми услугами и преимуществами члена клуба.",
