"Descontos exclusivos":"Эксклюзивные скидки",
"Um cartão, várias formas de poupar! Associa o teu cartão bancário ao cartão de Sócio e usa-o nas lojas parceiras para teres descontos diretos ou saldo na tua carteira virtual, que podes trocar por quotas, bilhetes, camisolas ou qualquer produto oficial do Lisbon FC.":"Одна карта — много способов экономить! Привяжите банковскую карту к карте члена клуба и используйте её в магазинах-партнёрах, чтобы получать прямые скидки или баланс в виртуальном кошельке, который можно обменять на взносы, билеты, футболки или любой официальный товар Lisbon FC.",
