"Gerir Cookies":"Управлять cookie",
"Centro de preferências de privacidade":"Центр настроек конфиденциальности",
"Quando visita um website, este pode armazenar ou recolher informações no seu navegador, principalmente na forma de cookies. Esta informação pode ser sobre si, as suas preferências ou o seu dispositivo e é utilizada principalmente para fazer o website funcionar conforme o esperado. A informação normalmente não o identifica diretamente, mas pode dar-lhe uma experiência web mais personalizada. Uma vez que respeitamos o seu direito à privacidade, pode optar por não permitir alguns tipos de cookies. Clique nos cabeçalhos das diferentes categorias para saber mais e alterar as nossas configurações predefinidas. No entanto, o bloqueio de alguns tipos de cookies pode afetar a sua experiência no website e os serviços que podemos oferecer.":"Когда вы посещаете веб-сайт, он может сохранять или получать информацию в вашем браузере, в основном в виде файлов cookie. Эта информация может касаться вас, ваших предпочтений или вашего устройства и в основном используется для того, чтобы сайт работал так, как вы ожидаете. Обычно она не идентифицирует вас напрямую, но может сделать работу в интернете более персонализированной. Поскольку мы уважаем ваше право на конфиденциальность, вы можете запретить некоторые типы cookie. Нажимайте на заголовки разных категорий, чтобы узнать больше и изменить настройки по умолчанию. Однако блокировка некоторых типов cookie может повлиять на работу сайта и на услуги, которые мы можем предложить.",
"Mais informação":"Подробнее",
"Permitir todos":"Разрешить все",
"Gerir preferências de cookies":"Управление настройками cookie",
"Cookies estritamente necessários":"Строго необходимые cookie",
"Sempre ativos":"Всегда активны",
"Estes cookies são necessários para que o website funcione e não podem ser desligados nos nossos sistemas. Normalmente, eles só são configurados em resposta a ações levadas a cabo por si e que correspondem a uma solicitação de serviços, tais como definir as suas preferências de privacidade, iniciar sessão ou preencher formulários. Pode configurar o seu navegador para bloquear ou alertá-lo(a) sobre esses cookies, mas algumas partes do website não funcionarão. Estes cookies não armazenam qualquer informação pessoal identificável.":"Эти cookie необходимы для работы сайта и не могут быть отключены в наших системах. Обычно они устанавливаются только в ответ на ваши действия, равнозначные запросу услуг, например при настройке параметров конфиденциальности, входе в аккаунт или заполнении форм. Вы можете настроить браузер так, чтобы он блокировал эти cookie или предупреждал о них, но тогда некоторые части сайта не будут работать. Эти cookie не хранят никакой информации, позволяющей установить личность.",
"Cookies de terceiros":"Сторонние cookie",
"Cookies de funcionalidade":"Функциональные cookie",
"Estes cookies permitem que o site forneça uma funcionalidade e personalização melhoradas. Podem ser estabelecidos por nós ou por fornecedores externos cujos serviços adicionámos às nossas páginas. Se não permitir estes cookies algumas destas funcionalidades, ou mesmo todas, podem não atuar corretamente.":"Эти cookie позволяют сайту предоставлять расширенную функциональность и персонализацию. Они могут устанавливаться нами или сторонними поставщиками, чьи сервисы мы добавили на наши страницы. Если вы не разрешите эти cookie, некоторые или все эти функции могут работать некорректно.",
"Cookies de desempenho":"Cookie производительности",
"Estes cookies permitem-nos contar visitas e fontes de tráfego, para que possamos medir e melhorar o desempenho do nosso website. Eles ajudam-nos a saber quais são as páginas mais e menos populares e a ver como os visitantes se movimentam pelo website. Todas as informações recolhidas por estes cookies são agregadas e, por conseguinte, anónimas. Se não permitir estes cookies, não saberemos quando visitou o nosso site.":"Эти cookie позволяют нам подсчитывать посещения и источники трафика, чтобы измерять и улучшать работу сайта. Они помогают понять, какие страницы наиболее и наименее популярны, и увидеть, как посетители перемещаются по сайту. Вся собираемая информация агрегируется и, следовательно, анонимна. Если вы не разрешите эти cookie, мы не узнаем, когда вы посещали наш сайт.",
"Cookies de publicidade":"Рекламные cookie",
"Estes cookies podem ser estabelecidos através do nosso site pelos nossos parceiros de publicidade. Podem ser usados por essas empresas para construir um perfil sobre os seus interesses e mostrar-lhe anúncios relevantes em outros websites. Eles não armazenam diretamente informações pessoais, mas são baseados na identificação exclusiva do seu navegador e dispositivo de internet. Se não permitir estes cookies, terá menos publicidade direcionada.":"Эти cookie могут устанавливаться через наш сайт нашими рекламными партнёрами. Эти компании могут использовать их для составления профиля ваших интересов и показа релевантной рекламы на других сайтах. Они не хранят персональную информацию напрямую, а основаны на уникальной идентификации вашего браузера и устройства. Если вы не разрешите эти cookie, реклама будет менее таргетированной.",
