"Cada sócio é um passo em frente para o Lisbon FC. A tua quota ajuda a investir na formação de jovens talentos, a melhorar as infraestruturas do clube e a construir um futuro mais forte, dentro e fora de campo.":"Каждый член клуба — шаг вперёд для Lisbon FC. Ваш взнос помогает вкладываться в подготовку молодых талантов, улучшать инфраструктуру клуба и строить более сильное будущее на поле и за его пределами.",
"Estamos também a construir parcerias com marcas e lojas para, em breve, trazer aos nossos sócios descontos exclusivos em ainda mais lugares.":"Мы также налаживаем партнёрство с брендами и магазинами, чтобы вскоре предложить членам клуба эксклюзивные скидки в ещё большем количестве мест.",
