"Nascido em Lisboa a 14 de janeiro de 2009, Vicente Sousa é a figura fundadora do Lisbon Football Club. A 1 de março de 2023, juntamente com Duarte Gomes e Alfredo Bidarra, lançou oficialmente o projeto que viria a dar corpo ao clube, num momento que marcaria o início de uma nova história no futebol amador da capital. Com o passar do tempo, os seus dois companheiros de fundação afastaram-se da direção, deixando Vicente Sousa como atual presidente e dono do Lisbon FC, cargo que acumula com a sua paixão de sempre: jogar.":"Висенте Соуза родился в Лиссабоне 14 января 2009 года и является основателем Lisbon Football Club. 1 марта 2023 года вместе с Дуарте Гомешем и Альфреду Бидаррой он официально запустил проект, ставший основой клуба, — момент, положивший начало новой истории любительского футбола столицы. Со временем двое его соучредителей отошли от руководства, и Висенте Соуза стал нынешним президентом и владельцем Lisbon FC, совмещая эту роль со своей давней страстью — игрой.",
"Guarda-redes do plantel, Vicente Sousa destaca-se pela sua solidez a defender remates de longa distância e pela coragem nos duelos de um-para-um, qualidades que fazem dele um dos últimos bastiões da equipa. A sua liderança dentro de campo espelha o papel que desempenha fora dele, à frente dos destinos do clube que ajudou a construir desde a primeira hora.":"Вратарь команды Висенте Соуза выделяется надёжностью при дальних ударах и смелостью в единоборствах один на один — качествами, которые делают его одним из последних бастионов команды. Его лидерство на поле отражает роль, которую он играет вне его, возглавляя клуб, который помогал строить с самого первого часа.",
"Para além do futebol, Vicente Sousa é um empreendedor nato, com o ambicioso objetivo de se tornar bilionário antes dos 30 anos. Gere vários projetos e negócios em paralelo, sendo o Lisbon FC aquele que ocupa o lugar central nas suas ambições — um clube que nasceu de uma ideia entre amigos e que, sob a sua visão, continua a crescer e a construir a sua própria história.":"Помимо футбола, Висенте Соуза — прирождённый предприниматель с амбициозной целью стать миллиардером до 30 лет. Он параллельно ведёт несколько проектов и бизнесов, и центральное место в его планах занимает Lisbon FC — клуб, родившийся из идеи друзей, который под его руководством продолжает расти и писать собственную историю.",
"Vicente Sousa, Guarda-Redes e presidente-fundador do Lisbon FC.":"Висенте Соуза, вратарь и президент-основатель Lisbon FC.",
