"Qua, 01 Mar 2023":"Ср, 01 мар 2023",
"Sem mais jogadores disponíveis, Sánchez voltou a bater, mas rematou ao meio e falhou, selando a vitória da equipa adversária por 2-1 nas grandes penalidades.":"Других игроков не осталось, и Санчес снова подошёл к мячу, но пробил по центру и промахнулся — это закрепило победу соперника 2:1 в серии пенальти.",
"Um minuto depois, uma perda de bola de Rodrigues no meio-campo permitiu à equipa adversária um simples passe rasteiro para empatar a partida em 2-2.":"Через минуту потеря мяча Родригешем в центре поля позволила сопернику простой передачей низом сравнять счёт — 2:2.",
"Ainda no reatamento do jogo após o golo, este jogador provocou Sánchez ao tocar na bola antes do pontapé de saída, sendo amarelado pelo árbitro Tomé Beles.":"При возобновлении игры после гола этот игрок спровоцировал Санчеса, коснувшись мяча до начального удара, и получил жёлтую карточку от судьи Томе Белеша.",
"Qua, 15 Mar 2023":"Ср, 15 мар 2023",
"Logo no pontapé de saída que se seguiu ao golo, o avançado adversário viu Vicente Sousa adiantado e rematou em arco desde o meio-campo, surpreendendo o guarda-redes.":"Сразу после розыгрыша с центра нападающий соперника заметил, что Висенте Соуза вышел из ворот, и закрученным ударом с центра поля застал вратаря врасплох.",
