"Identificadores de Redes Sociais, NIF, NISS, número utente de saúde, dados complementares":"Идентификаторы в социальных сетях, ИНН (NIF), номер социального страхования (NISS), номер пациента системы здравоохранения, дополнительные данные",
"Dados bancários":"Банковские данные",
"IBAN, dados de identificação bancária":"IBAN, банковские идентификационные данные",
"Dados profissionais":"Профессиональные данные",
"Entidade empregadora, função, categoria, carteira profissional":"Работодатель, должность, категория, профессиональное удостоверение",
"Dados de acesso à conta Lisbon FC":"Данные для входа в аккаунт Lisbon FC",
"Username, password":"Имя пользователя, пароль",
"Imagem":"Изображение",
"O Grupo Lisbon FC preocupa-se especialmente com a proteção dos direitos dos menores, pelo que a recolha de dados pessoais de menores de 18 anos está, na generalidade dos casos, dependente do consentimento dos respetivos pais/responsáveis pela tutela parental.":"Группа Lisbon FC уделяет особое внимание защите прав несовершеннолетних, поэтому сбор персональных данных лиц младше 18 лет в большинстве случаев возможен только с согласия их родителей или законных представителей.",
"O Grupo Lisbon FC, trata estes dados nos termos da legislação aplicável, para diversas finalidades, entre as quais:":"Группа Lisbon FC обрабатывает эти данные в соответствии с применимым законодательством для различных целей, в том числе:",
